45	    /** Every page query served so far, oldest first. */
46	    public synchronized List<PageQuery> pageQueries() {
47	        return List.copyOf(pageQueries);
48	    }
49	
50	    /** The result of every count query served so far, oldest first. */
51	    public synchronized List<Integer> countQueries() {
52	        return List.copyOf(countQueries);
53	    }
54	
55	    /** Total number of rows served by all page queries so far. */
56	    public synchronized int rowsFetched() {
57	        return pageQueries.stream().mapToInt(PageQuery::rowsReturned).sum();
58	    }
59	
60	    /** Forgets everything recorded so far. Tests call this before a scenario. */
61	    public synchronized void clear() {
62	        pageQueries.clear();
63	        countQueries.clear();
